  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const { q } = Object.fromEntries(new URLSearchParams(location.search));

  useEffect(() => {
    setLoading(true);
    fetch(`/api/search?q=${encodeURIComponent(q)}`)
      .then(r => r.json())
